#!/usr/bin/env python3\n\nimport argparse\nimport pathlib\nimport subprocess\nimport sys\n\n\ndef generate_dockerfile(base_image: str, dest: pathlib.Path) -> None:\n    """Write a Dockerfile that uses *base_image* and runs *entrypoint.sh* as ENTRYPOINT."""\n    dockerfile_content = f"""FROM {base_image}\nWORKDIR /app\nCOPY entrypoint.sh /app/entrypoint.sh\nRUN chmod +x /app/entrypoint.sh\nENTRYPOINT [\"/app/entrypoint.sh\"]\n"""\n    dest.write_text(dockerfile_content)\n\n\ndef generate_entrypoint(message: str, dest: pathlib.Path) -> None:\n    """Create a tiny shell script that echoes *message* and then execs any passed command."""\n    script_content = f"""#!/bin/sh\n\n# Print the whimsical potion message\nprintf '%s\\n' \"{message}\"\n\n# Execute the command given to the container (if any)\nexec \"$@\"\n"""\n    dest.write_text(script_content)\n\n\ndef build_image(tag: str, context: pathlib.Path) -> str:\n    """Run ``docker build`` and return its stdout. Raises RuntimeError on failure."""\n    result = subprocess.run(\n        ["docker", "build", "-t", tag, str(context)],\n        capture_output=True,\n        text=True,\n    )\n    if result.returncode != 0:\n        raise RuntimeError(f"Docker build failed: {result.stderr}")\n    return result.stdout\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description="Create a whimsical Docker image that prints a custom message.")\n    parser.add_argument("--base", default="alpine:3.18", help="Base Docker image (default: alpine:3.18)")\n    parser.add_argument("--message", required=True, help="Message to display when the container starts")\n    parser.add_argument("--tag", required=True, help="Tag for the built Docker image")\n    args = parser.parse_args()\n\n    workdir = pathlib.Path('.docker_potion')\n    workdir.mkdir(exist_ok=True)\n\n    generate_dockerfile(args.base, workdir / 'Dockerfile')\n    generate_entrypoint(args.message, workdir / 'entrypoint.sh')\n\n    try:\n        build_output = build_image(args.tag, workdir)\n        print(build_output)\n    except RuntimeError as exc:\n        sys.stderr.write(str(exc) + '\n')\n        sys.exit(1)\n\n\nif __name__ == "__main__":\n    main()\n
